// 修正後の式 Math.round(s*(1-d)*(1-b)) が、厳密な有理数計算の四捨五入(half-up)とずれる件数を数える
const exact = (s, dPermille, bPermille) => {
  // s*(1000-d)*(1000-b)/1e6 を整数で half-up
  const num = BigInt(s) * BigInt(1000 - dPermille) * BigInt(1000 - bPermille);
  return Number((num + 500000n) / 1000000n);
};
let n = 0, diff = 0; const ex = [];
for (const dp of [0, 50, 100, 150, 200, 250, 300, 500]) for (const bp of [0, 50]) for (let s = 0; s <= 20000; s++) {
  n++;
  const f = Math.round(s * (1 - dp / 1000) * (1 - bp / 1000));
  const e = exact(s, dp, bp);
  if (f !== e) { diff++; if (ex.length < 8) ex.push({ s, d: dp / 1000, b: bp / 1000, float: f, exact: e }); }
}
console.log({ n, diff }); console.log(ex);
// d=0 だけ
let d0 = 0; for (const bp of [0, 50]) for (let s = 0; s <= 20000; s++) if (Math.round(s * (1 - 0) * (1 - bp / 1000)) !== exact(s, 0, bp)) d0++;
console.log('d=0 diffs', d0);

